async function clickUntil(pattern, max=8000) {
  const start=Date.now();
  while (Date.now()-start<max) {
    const d=sdk.getDialog();
    if (!d?.isOpen) { await sdk.waitForTicks(1).catch(()=>{}); continue; }
    const opt=d.options?.find(o => pattern.test(o.text));
    if (opt) { await sdk.sendClickDialog(opt.index); await sdk.waitForTicks(1).catch(()=>{}); return true; }
    await sdk.sendClickDialog(0); await sdk.waitForTicks(1).catch(()=>{});
  }
  return false;
}
