  const invA=sdk.findInventoryItem(/steel arrow|iron arrow|bronze arrow/i);
  if(invA) await bot.equipItem(invA).catch(()=>{});
}
function choose(){
  const pref = [/guard/i,/thief/i,/mugger/i,/dark wizard/i,/tramp/i,/man|woman/i];
  const ns=sdk.getNearbyNpcs().filter(n=>n.options?.includes('Attack')&&!n.inCombat&&n.combatLevel>0&&n.combatLevel<=30);
  return ns.sort((a,b)=>{
    const sa=pref.findIndex(r=>r.test(a.name));
    const sb=pref.findIndex(r=>r.test(b.name));
    const pa=sa<0?99:sa, pb=sb<0?99:sb;
    return pa-pb || b.combatLevel-a.combatLevel || a.distance-b.distance;
  })[0];
}
