function chooseSpell() {
  const lvl = sdk.getSkill('Magic').baseLevel;
  if (lvl >= 11 && count('body rune') >= 1 && count('water rune') >= 3 && count('earth rune') >= 2) return ['Weaken', SPELLS.WEAKEN];
  if (lvl >= 9 && count('mind rune') >= 1 && count('earth rune') >= 2 && count('air rune') >= 1) return ['Earth Strike', SPELLS.EARTH];
  if (lvl >= 5 && count('mind rune') >= 1 && count('water rune') >= 1 && count('air rune') >= 1) return ['Water Strike', SPELLS.WATER];
  if (count('mind rune') >= 1 && count('air rune') >= 1) return ['Wind Strike', SPELLS.WIND];
  if (lvl >= 3 && count('body rune') >= 1 && count('water rune') >= 3 && count('earth rune') >= 2) return ['Confuse', SPELLS.CONFUSE];
  return null;
}
