await bot.walkTo(3249, 3201, 3);
while (count(/yew logs/i) < 22 && Date.now() - start < 80000 && inv().length < 28) {
  await bot.dismissBlockingUI();
  const before = { logs: count(/yew logs/i), xp: skill('Woodcutting').experience, tick: sdk.getState().tick };
  const yew = sdk.getNearbyLocs().filter(l => /yew/i.test(l.name) && l.options?.some(o=>/chop/i.test(o))).sort((a,b)=>a.distance-b.distance)[0];
  if (!yew) { await sleep(1000); continue; }
  const r = await bot.chopTree(yew);
  const after = { logs: count(/yew logs/i), xp: skill('Woodcutting').experience, tick: sdk.getState().tick };
  if (after.logs > before.logs) events.push({ logs: after.logs, tickDelta: after.tick - before.tick, wcXp: after.xp });
  else events.push({ miss:true, msg:r.message, logs:after.logs });
}
return { elapsedMs:Date.now()-start, pos:pos(), logs:count(/yew logs/i), events:events.slice(-12), fletch:skill('Fletching'), wc:skill('Woodcutting'), inv:inv().map(i=>({slot:i.slot,name:i.name,count:i.count})) };

